/* --------------------------------------------------- presets & data charts */

test("CSV and JSON become labels + series", () => {
	const csv = parseChartData("运动,力量,心肺\nW1,40,12\nW2,34,20");
	assert.deepEqual(csv.labels, ["W1", "W2"]);
	assert.deepEqual(csv.series.map((one) => one.name), ["力量", "心肺"]);
	assert.deepEqual(csv.series[1].values, [12, 20]);

	const json = parseChartData('[{"week":"W1","力量":40,"心肺":12},{"week":"W2","力量":34,"心肺":20}]');
	assert.deepEqual(json.labels, ["W1", "W2"]);
	assert.deepEqual(json.series.map((one) => one.name), ["力量", "心肺"]);

	const shaped = parseChartData('{"labels":["W1","W2"],"series":{"力量":[40,34]}}');
	assert.deepEqual(shaped.series[0].values, [40, 34]);
});

test("bars, hbars and stack normalise sizes against the data", () => {
	const data = parseChartData("W,力量,心肺\nW1,40,10\nW2,10,30");
	const bars = chartMarkup("bars", data);
	assert.ok(bars.includes('style="height:100%"'), "the max value fills the column");
	assert.ok(bars.includes('style="height:25%"'));

	const hbars = chartMarkup("hbars", data);
	assert.ok(hbars.includes('style="width:100%"'));
	assert.ok(hbars.includes("hbar-val"));

	const stack = chartMarkup("stack", data);
	assert.ok(stack.includes("stack-seg c2"), "second series gets its own colour");
	const heights = [...stack.matchAll(/height:([\d.]+)%/g)].map((one) => Number(one[1]));
	assert.ok(heights.length === 4);
});

test("line charts compute their own viewBox coordinates", () => {
	const data = parseChartData("W,v\nW1,10\nW2,30\nW3,20");
	const line = chartMarkup("line", data);
	assert.ok(line.includes('viewBox="0 0 320 180"'));
	assert.ok(line.includes('class="series"'));
	assert.ok(/M24,\d+/.test(line), "first point sits on the left padding");
	const path = /<path class="series" d="M([^"]+)"/.exec(line)[1];
	const points = path.split(" L").map((one) => one.split(",").map(Number));
	assert.equal(points.length, 3);
	const maxPoint = points.reduce((best, one) => (one[1] < best[1] ? one : best));
	assert.ok(maxPoint[1] < 100, "the largest value is drawn near the top");
});

test("heat and donut map values into intensity and percentage", () => {
	const heat = chartMarkup("heat", parseChartData("d,v\na,0\nb,10\nc,100"));
	assert.ok(heat.includes('heat-cell '));
	assert.ok(heat.includes("heat-cell l5"));
	assert.ok(heat.includes('class="heat-cell"'), "a zero day is an empty cell");

	// A donut is "first bucket over the total": two rows, 18 of 18+7.
	const donut = chartMarkup("donut", parseChartData("状态,次数\n已完成,18\n未完成,7"));
	assert.ok(donut.includes("--p:72%"));
	assert.ok(donut.includes("72%"));
});

test("bad chart data is refused with a code", () => {
	assert.throws(() => parseChartData(""), (error) => error.code === "HTML_BAD_DATA");
	assert.throws(() => parseChartData("only-a-header"), (error) => error.code === "HTML_BAD_DATA");
	assert.throws(() => parseChartData("a\n1"), (error) => error.code === "HTML_BAD_DATA");
	assert.throws(() => chartMarkup("pie", parseChartData("a,v\n1,2")), (error) => error.code === "HTML_BAD_ARGS");
});

test("style resolution: explicit beats named preset beats project default", () => {
	const presets = {
		default: { tokens: { "--accent": "#111111", "--c2": "#222222" }, theme: "dark" },
		names: { brand: { tokens: { "--accent": "#c2410c" }, width: "wide" } }
	};
	const fromDefault = resolveStyle({ preset: "", theme: "auto", width: "", density: "", tokens: {} }, presets);
	assert.equal(fromDefault.tokens["--accent"], "#111111");
	assert.equal(fromDefault.theme, "dark");

	const named = resolveStyle({ preset: "brand", theme: "auto", width: "", density: "", tokens: {} }, presets);
	assert.equal(named.tokens["--accent"], "#c2410c", "named preset wins over default");
	assert.equal(named.tokens["--c2"], "#222222", "default tokens still fill the gaps");
	assert.equal(named.width, "wide");

	const explicit = resolveStyle({ preset: "brand", theme: "light", width: "", density: "", tokens: { "--accent": "#09f" } }, presets);
	assert.equal(explicit.theme, "light");
	assert.equal(explicit.tokens["--accent"], "#09f");
});

test("a stored preset reads back as a one-line summary", () => {
	const summary = styleSummary({ theme: "dark", width: "wide", density: "compact", tokens: { "--accent": "#c2410c" } });
	assert.ok(summary.includes("theme=dark"));
	assert.ok(summary.includes("width=wide"));
	assert.ok(summary.includes("--accent"));
	assert.equal(styleSummary({}), "(empty)");
});

test("tokens declared on the page are what drift detection compares", () => {
	const page = scratchDocument({ title: "t", tokens: { "--accent": "#c2410c", "--c2": "#0891b2" } });
	const declared = declaredTokens(page);
	assert.equal(declared["--accent"], "#c2410c");
	assert.equal(declared["--c2"], "#0891b2");
});
